	   !gis_deleted[i] ) {
	printf(" ---  STATIC");
      }
      for ( j = 0; j < gnum_initial_predicate[i]; j++ ) {
	printf("\n");
	print_Fact( &(ginitial_predicate[i][j]) );
      }
    }
    printf("\n\nindividual functions:");
    for ( i = 0; i < gnum_functions; i++ ) {
      printf("\n\n%s:", gfunctions[i]);
      if ( !gis_changed[i] ) {
