  for ( i = 0; i < gnum_plan_ops; i++ ) {
    printf("%4d: ", i);
    print_op_name( gplan_ops[i] );
    if ( i < gnum_plan_ops-1 ) {
      printf("\n     ");
    }
    if ( goptimization_established ) {
      cost += gop_conn[gplan_ops[i]].cost;
    }
  }
  if ( goptimization_established ) {
    printf("\nplan cost: %f", cost);
  }

}

