Bool LESS( int a, int b )

{

  if ( a == INFINITY ) {
    return FALSE;
  }

  if ( b == INFINITY ) {
    return TRUE;
  }

  return ( a < b ? TRUE : FALSE );

}



Bool FLOAT_LE( float a, float b )

{

  if ( b == INFINITY ) {
    return TRUE;
  }

  if ( a == INFINITY ) {
    return FALSE;
  }

  return ( a <= b ? TRUE : FALSE );

}














