    if ( gop_conn[gef_conn[lE[i]].op].axiom ) {
      if ( gcmd_line.debug ) {
	printf(" -- axiom, skipping it!");
      }
      continue;
    }
    if ( gcmd_line.debug ) {
      printf(" -- adding it!");
    }
    gop_conn[gef_conn[lE[i]].op].is_in_A = TRUE;
    gA[gnum_A++] = gef_conn[lE[i]].op;
  }

}



void get_A( State *S )

{

  int i;

  initialize_fixpoint( S );

  for ( i = 0; i < lnum_F; i++ ) {
    activate_ft( lF[i], 0 );
  }
  for ( i = 0; i < lnum_0P_E; i++ ) {
    if ( gef_conn[l0P_E[i]].in_E ) {
      continue;
    }
    new_ef( l0P_E[i] );
