"""Worker process that hosts the (untrusted) agent policy and talks to the harness.

READ-ONLY. Launched by run_eval.py, one process per episode, with stdin/stdout as
a JSON-lines channel and stderr as a log. The worker never touches the simulator
or the model server: every action is executed by the harness (which owns the
simulator and decides success), and every model request is relayed through the
harness, which meters the per-episode budget and holds the server credentials.

Protocol (one JSON object per line):
  harness -> worker : {"type": "init", env, seed}
  harness -> worker : {"type": "reset", instruction, obs, budget}
  harness -> worker : {"type": "act", obs, history, budget}
  harness -> worker : {"type": "observe", record, obs, budget}
  harness -> worker : {"type": "shutdown"}
  worker -> harness : {"type": "vlm", messages, max_tokens, temperature, response_format, n}
  harness -> worker : {"type": "vlm_result", texts: [..], calls_left}
  worker -> harness : {"type": "ready"} | {"type": "ok"} | {"type": "plan", actions}
                      | {"type": "continue", value} | {"type": "error", message}

Anything the policy prints goes to stderr (sys.stdout is redirected before the
policy module is imported), so the protocol channel stays clean. A single reader
thread owns stdin: "vlm_result" lines go to the (one at a time) model caller,
every other line is a command for the main loop, so a policy may call the model
from helper threads without racing the command channel.
"""
from __future__ import annotations

import json
import os
import queue
import sys
import threading
import traceback

_HERE = os.path.dirname(os.path.abspath(__file__))
if _HERE not in sys.path:
    sys.path.insert(0, _HERE)
_EB_ROOT = os.path.dirname(_HERE)
if _EB_ROOT not in sys.path:
    sys.path.insert(1, _EB_ROOT)

_OUT = sys.__stdout__
_IN = sys.__stdin__
sys.stdout = sys.stderr  # policy prints must not corrupt the protocol channel

from agent_api import Budget, EnvSpec, Observation, StepRecord, VLMClient  # noqa: E402

_EOF = object()
_commands: "queue.Queue[object]" = queue.Queue()
_vlm_replies: "queue.Queue[object]" = queue.Queue()
_send_lock = threading.Lock()
_vlm_lock = threading.Lock()


def _send(obj: dict) -> None:
    with _send_lock:
        _OUT.write(json.dumps(obj) + "\n")
        _OUT.flush()


def _reader() -> None:
    while True:
        line = _IN.readline()
        if not line:
            _vlm_replies.put(_EOF)
            _commands.put(_EOF)
            return
        try:
            msg = json.loads(line)
        except json.JSONDecodeError:
            _commands.put({"type": "_garbage", "line": line[:200]})
            continue
        if isinstance(msg, dict) and msg.get("type") == "vlm_result":
            _vlm_replies.put(msg)
        else:
            _commands.put(msg)


def _recv() -> dict:
    msg = _commands.get()
    if msg is _EOF:
        raise SystemExit(0)
    return msg


def _jsonable(x):
    """Coerce numpy scalars / tuples in a plan into plain JSON types."""
    if isinstance(x, (list, tuple)):
        return [_jsonable(v) for v in x]
    if isinstance(x, dict):
        return {str(k): _jsonable(v) for k, v in x.items()}
    if hasattr(x, "item") and callable(getattr(x, "item")):
        try:
            return x.item()
        except Exception:  # noqa: BLE001
            pass
    if isinstance(x, (int, float, str, bool)) or x is None:
        return x
    return str(x)


class _RPCVLMClient(VLMClient):
    def __init__(self) -> None:
        self._calls_left = 0

    def chat(self, messages, *, max_tokens=4096, temperature=0.0, response_format=None, n=1):
        req = {"type": "vlm", "messages": _jsonable(list(messages)), "max_tokens": int(max_tokens),
               "temperature": None if temperature is None else float(temperature), "n": int(n),
               "response_format": _jsonable(response_format) if response_format else None}
        with _vlm_lock:
            _send(req)
            rep = _vlm_replies.get()
        if rep is _EOF:
            raise SystemExit(0)
        self._calls_left = int(rep.get("calls_left", 0))
        return [str(t) for t in rep.get("texts", [])]

    def chat_with_tools(self, messages, tools, *, max_tokens=4096, temperature=None, tool_choice="auto"):
        req = {"type": "vlm", "messages": _jsonable(list(messages)), "max_tokens": int(max_tokens),
               "temperature": None if temperature is None else float(temperature), "n": 1,
               "tools": _jsonable(list(tools)), "tool_choice": str(tool_choice)}
        with _vlm_lock:
            _send(req)
            rep = _vlm_replies.get()
        if rep is _EOF:
            raise SystemExit(0)
        self._calls_left = int(rep.get("calls_left", 0))
        msgs = rep.get("messages") or [{"role": "assistant", "content": "", "tool_calls": []}]
        return msgs[0]

    @property
    def calls_left(self) -> int:
        return self._calls_left


def main() -> None:
    threading.Thread(target=_reader, name="rpc-reader", daemon=True).start()
    vlm = _RPCVLMClient()
    agent = None
    while True:
        msg = _recv()
        t = msg.get("type")
        try:
            if t == "_garbage":
                _send({"type": "error", "message": f"protocol garbage: {msg.get('line')!r}"})
            elif t == "init":
                spec = EnvSpec.from_dict(msg["env"])
                vlm._calls_left = spec.max_vlm_calls
                import custom_agent  # the editable module, imported only here
                agent = custom_agent.CustomAgent(vlm, spec, int(msg["seed"]))
                _send({"type": "ready"})
            elif t == "reset":
                agent.reset(str(msg["instruction"]), Observation.from_dict(msg["obs"]),
                            Budget.from_dict(msg["budget"]))
                _send({"type": "ok"})
            elif t == "act":
                plan = agent.act(Observation.from_dict(msg["obs"]),
                                 [StepRecord.from_dict(r) for r in msg.get("history", [])],
                                 Budget.from_dict(msg["budget"]))
                if plan is None:
                    plan = []
                if not isinstance(plan, (list, tuple)):
                    plan = [plan]
                _send({"type": "plan", "actions": _jsonable(list(plan))})
            elif t == "observe":
                keep = agent.observe(StepRecord.from_dict(msg["record"]), Observation.from_dict(msg["obs"]),
                                     Budget.from_dict(msg["budget"]))
                _send({"type": "continue", "value": bool(keep)})
            elif t == "shutdown":
                _send({"type": "ok"})
                return
            else:
                _send({"type": "error", "message": f"unknown message type {t!r}"})
        except SystemExit:
            raise
        except BaseException as exc:  # noqa: BLE001 - report, do not die silently
            traceback.print_exc(file=sys.stderr)
            _send({"type": "error", "message": f"{type(exc).__name__}: {exc}"[:2000]})


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Evaluation harness: runs a CustomAgent over one EmbodiedBench embodiment.

READ-ONLY. This is the TRUSTED side. It owns the simulator (which decides
success), the per-episode budget meter and the model-server credentials. The
policy under test never runs in this process: every episode gets its own worker
subprocess (agent_worker.py) -- as an unprivileged uid when the harness is root,
or through $MLSBENCH_RUN_UNTRUSTED under the Harbor verifier (a fresh uid per
episode, killed and swept when the episode ends) -- that receives only
observations, feedback and its own history, and returns actions. Model requests
from the policy are relayed through this process so the budget is enforced here.

Protocol per episode (fixed by the task, identical for every policy):
  * the embodiment's EmbodiedBench limits (eb_envs.LIMITS): environment steps
    per episode and invalid actions per episode;
  * at most MAX_VLM_CALLS[env] model requests per episode (plans, checks,
    reflections, descriptions -- everything; `n` samples count `n`);
  * at most MAX_TOKENS_PER_CALL completion tokens and MAX_IMAGES_PER_CALL
    images per request; EPISODE_WALL_CLOCK_S per episode;
  * success is the simulator's own task-success predicate.

Where the episodes come from: the held-out EmbodiedBench evaluation episodes are
not part of the image (the navigation targets, the rearrangement goals and the
manipulation scene files are answer keys). Under Harbor they arrive in the
verifier-only mount (/tests/meta/eb_episodes.tar, staged from the task's
host-side holdout/), which is extracted into a 0700 temporary directory while
the policy worker runs as another uid; /tests/meta is sealed for the run.
"""
