# ---------------------------------------------------------------------------
# Protocol constants (the task's fixed budget; not tunable by the policy)
# ---------------------------------------------------------------------------
MAX_VLM_CALLS = {"habitat": 60, "navigation": 40, "manipulation": 30}   # 2x the env-step limit
MAX_TOKENS_PER_CALL = 4096      # EmbodiedBench remote_model.max_completion_tokens
MAX_IMAGES_PER_CALL = 10
MAX_N_PER_CALL = 8
LLM_TIMEOUT_S = 900.0
EPISODE_WALL_CLOCK_S = 2400.0
WORKER_REPLY_TIMEOUT_S = 1200.0
MAX_ACT_CALLS_FACTOR = 3        # act() calls per episode <= factor * (env steps + invalid limit)
WORKER_UID = 65534
SIM_RETRIES = 2


class SimError(Exception):
    """The simulator (not the policy) failed during reset/step."""


# ---------------------------------------------------------------------------
# Episode staging (trusted side)
# ---------------------------------------------------------------------------
_RESTORE_MODES: list = []


def _seal_dir(path: str) -> None:
    try:
        st = os.stat(path)
    except OSError:
        return
    if os.geteuid() != 0:
        return
    if stat.S_IMODE(st.st_mode) & 0o077:
        os.chmod(path, 0o700)
        _RESTORE_MODES.append((path, stat.S_IMODE(st.st_mode)))
        print(f"[harness] sealed {path} (was {oct(stat.S_IMODE(st.st_mode))})", flush=True)


def _restore_modes() -> None:
    for path, mode in _RESTORE_MODES:
        try:
            os.chmod(path, mode)
        except OSError:
            pass


def stage_episodes(archive: str | None, root: str | None) -> str:
    """Return a directory holding habitat/ navigation/ manipulation/ + index.json, readable by root only."""
    if archive:
        tmp = tempfile.mkdtemp(prefix="mlsb_eb_episodes_")      # 0700
        with tarfile.open(archive, "r:*") as tf:
            for m in tf.getmembers():
                if m.name.startswith("/") or ".." in m.name.split("/") or m.issym() or m.islnk():
                    raise RuntimeError(f"refusing archive member {m.name!r}")
            tf.extractall(tmp)
        atexit.register(shutil.rmtree, tmp, True)
        print(f"[harness] held-out episodes extracted from {archive} into a 0700 tmpdir", flush=True)
        return os.path.join(tmp, "eb_episodes")
    if not root:
        raise SystemExit("one of --episodes-archive / --episodes-root is required")
    if os.geteuid() == 0:
        _seal_dir(root)
    return root


