class _HTTPError(Exception):
    def __init__(self, code: int, msg: str):
        super().__init__(f"HTTP {code}: {msg}")
        self.code, self.msg = code, msg


class _UDSHTTPConnection(http.client.HTTPConnection):
    def __init__(self, path: str, timeout: float):
        super().__init__("localhost", timeout=timeout)
        self._uds_path = path

    def connect(self):
        self.sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        self.sock.settimeout(self.timeout)
        self.sock.connect(self._uds_path)


def _open_connection(base_url: str, timeout: float):
    u = urllib.parse.urlsplit(base_url)
    if u.scheme == "unix":
        return _UDSHTTPConnection(urllib.parse.unquote(u.path), timeout)
    return http.client.HTTPConnection(u.hostname, u.port or 80, timeout=timeout)


def _sanitize_messages(messages) -> tuple[list, int]:
    """Keep only text and data-URL image parts; count images."""
    out, n_img = [], 0
    if not isinstance(messages, list):
        raise ValueError("messages must be a list")
    for m in messages:
        if not isinstance(m, dict):
            raise ValueError("message must be a dict")
        role = str(m.get("role", "user"))
        if role not in ("system", "user", "assistant", "tool"):
            role = "user"
        content = m.get("content", "")
        if role == "tool":
            out.append({"role": "tool", "tool_call_id": str(m.get("tool_call_id", ""))[:128],
                        "content": str(content if content is not None else "")})
            continue
        if role == "assistant" and m.get("tool_calls"):
            calls = []
            for c in m.get("tool_calls") or []:
                fn = (c or {}).get("function") or {}
                calls.append({"id": str(c.get("id", ""))[:128], "type": "function",
                              "function": {"name": str(fn.get("name", ""))[:128],
                                           "arguments": str(fn.get("arguments", ""))}})
            out.append({"role": "assistant", "content": None if content is None else str(content),
                        "tool_calls": calls})
            continue
        if content is None:
            content = ""
        if isinstance(content, str):
            out.append({"role": role, "content": content})
            continue
        parts = []
        for p in content if isinstance(content, list) else []:
            if not isinstance(p, dict):
                continue
            if p.get("type") == "text":
                parts.append({"type": "text", "text": str(p.get("text", ""))})
            elif p.get("type") == "image_url":
                url = str((p.get("image_url") or {}).get("url", ""))
                if not url.startswith("data:image/"):
                    raise ValueError("only data:image/... URLs are accepted")
                parts.append({"type": "image_url", "image_url": {"url": url}})
                n_img += 1
        out.append({"role": role, "content": parts})
    return out, n_img


def _sanitize_response_format(rf):
    if not rf:
        return None
    if not isinstance(rf, dict):
        return None
    if rf.get("type") == "json_object":
        return {"type": "json_object"}
    if rf.get("type") == "json_schema" and isinstance(rf.get("json_schema"), dict):
        js = rf["json_schema"]
        return {"type": "json_schema", "json_schema": {"name": str(js.get("name", "output"))[:64],
                                                        "schema": js.get("schema", {})}}
    return None


class VLMRelay:
    def __init__(self, base_url: str, model: str, api_key: str, seed: int, ep_idx: int, max_calls: int):
        self.base_url = base_url.rstrip("/")
        self.model = model
        self.api_key = api_key
        self.seed = seed
        self.ep_idx = ep_idx
        self.max_calls = max_calls
        self.calls_used = 0
        self.prompt_tokens = 0
        self.completion_tokens = 0
        self.errors = 0

    def request(self, req: dict) -> dict:
        n = max(1, min(int(req.get("n", 1) or 1), MAX_N_PER_CALL))
        if self.calls_used + n > self.max_calls:
            return {"type": "vlm_result", "texts": [""] * n, "calls_left": max(0, self.max_calls - self.calls_used),
                    "error": "budget", "messages": [{"role": "assistant", "content": "", "tool_calls": []}]}
        self.calls_used += n
        texts = [""] * n
        try:
            messages, n_img = _sanitize_messages(req.get("messages"))
            if n_img > MAX_IMAGES_PER_CALL:
                raise ValueError(f"{n_img} images > MAX_IMAGES_PER_CALL={MAX_IMAGES_PER_CALL}")
        except Exception as e:  # noqa: BLE001
            self.errors += 1
            print(f"[vlm] rejected request on episode {self.ep_idx}: {e}", file=sys.stderr)
            return {"type": "vlm_result", "texts": texts, "calls_left": self.max_calls - self.calls_used,
                    "error": str(e)[:200], "messages": [{"role": "assistant", "content": "", "tool_calls": []}]}
        body = {
            "model": self.model, "messages": messages, "n": n,
            "max_tokens": max(1, min(int(req.get("max_tokens", MAX_TOKENS_PER_CALL) or 1), MAX_TOKENS_PER_CALL)),
            "seed": (self.seed * 100003 + self.ep_idx * 7919 + self.calls_used) % (2 ** 31),
        }
        if req.get("temperature") is not None:     # None = the model's own sampling defaults
            body["temperature"] = max(0.0, min(float(req.get("temperature") or 0.0), 1.5))
        rf = _sanitize_response_format(req.get("response_format"))
        if rf:
            body["response_format"] = rf
        tools = req.get("tools")
        with_tools = isinstance(tools, list) and len(tools) > 0
        tool_msgs = None
        if with_tools:
            body["tools"] = [{"type": "function", "function": {
                "name": str((t.get("function") or {}).get("name", ""))[:64],
                "description": str((t.get("function") or {}).get("description", ""))[:8000],
                "parameters": (t.get("function") or {}).get("parameters") or {"type": "object", "properties": {}}}}
                for t in tools[:16] if isinstance(t, dict)]
            body["tool_choice"] = "none" if req.get("tool_choice") == "none" else "auto"
            body["n"] = 1
        for attempt in range(4):
            try:
                data = json.dumps(body).encode()
                conn = _open_connection(self.base_url, LLM_TIMEOUT_S)
                try:
                    conn.request("POST", "/v1/chat/completions", body=data,
                                 headers={"Content-Type": "application/json",
                                          "Authorization": f"Bearer {self.api_key or 'none'}"})
                    resp = conn.getresponse()
                    payload = resp.read().decode(errors="replace")
                finally:
                    conn.close()
                if resp.status != 200:
                    raise _HTTPError(resp.status, payload[:500])
                out = json.loads(payload)
                choices = out.get("choices", [])
                texts = [((c.get("message") or {}).get("content") or "") for c in choices]
                texts = (texts + [""] * n)[:n]
                if with_tools:
                    msg = (choices[0].get("message") or {}) if choices else {}
                    tool_msgs = [{"role": "assistant", "content": msg.get("content"),
                                  "tool_calls": [{"id": str(c.get("id")), "type": "function",
                                                  "function": {"name": str((c.get("function") or {}).get("name")),
                                                               "arguments": str((c.get("function") or {}).get("arguments"))}}
                                                 for c in (msg.get("tool_calls") or [])]}]
                usage = out.get("usage") or {}
                self.prompt_tokens += int(usage.get("prompt_tokens", 0) or 0)
                self.completion_tokens += int(usage.get("completion_tokens", 0) or 0)
                break
            except _HTTPError as e:
                self.errors += 1
                print(f"[vlm] HTTP {e.code} on episode {self.ep_idx}: {e.msg}", file=sys.stderr)
                if e.code == 400:
                    break
                time.sleep(2.0 * (attempt + 1))
            except Exception as e:  # noqa: BLE001
                self.errors += 1
                print(f"[vlm] error on episode {self.ep_idx}: {type(e).__name__}: {e}", file=sys.stderr)
                time.sleep(2.0 * (attempt + 1))
        out = {"type": "vlm_result", "texts": texts, "calls_left": self.max_calls - self.calls_used}
        if with_tools:
            out["messages"] = tool_msgs or [{"role": "assistant", "content": "", "tool_calls": []}]
        return out


# ---------------------------------------------------------------------------
# Worker subprocess (untrusted side)
# ---------------------------------------------------------------------------
_TRUSTED_SITE: dict = {}
_PTH_CODE = '\ndef _pth_dirs(sp):\n    # plain directory entries of *.pth files (eggs etc.), never the executable `import` lines;\n    # only entries that resolve inside the same site-packages directory are kept\n    out = []\n    try:\n        names = sorted(n for n in os.listdir(sp) if n.endswith(".pth"))\n    except OSError:\n        return out\n    for n in names:\n        try:\n            lines = open(os.path.join(sp, n)).read().splitlines()\n        except OSError:\n            continue\n        for line in lines:\n            line = line.strip()\n            if not line or line.startswith(("#", "import ", "import\\t")):\n                continue\n            d = os.path.realpath(os.path.join(sp, line))\n            if os.path.isdir(d) and d.startswith(os.path.realpath(sp) + os.sep):\n                out.append(d)\n    return out\n'


def trusted_site_path(python: str) -> str:
    env_val = os.environ.get("MLSB_WORKER_SITE")
    if env_val:
        return env_val
    if python not in _TRUSTED_SITE:
        code = ("import os, sys, sysconfig\n" + _PTH_CODE +
                "paths = [p for k in ('purelib', 'platlib') for p in [sysconfig.get_paths().get(k)] if p and os.path.isdir(p)]\n"
                "try:\n    import site\n    paths += [p for p in site.getsitepackages() if os.path.isdir(p) and p not in paths]\n"
                "except Exception:\n    pass\n"
                "paths += [d for p in list(paths) for d in _pth_dirs(p)]\n"
                "print(os.pathsep.join(dict.fromkeys(paths)))")
        out = subprocess.run([python, "-S", "-E", "-c", code], capture_output=True, text=True, timeout=60)
        _TRUSTED_SITE[python] = out.stdout.strip()
    return _TRUSTED_SITE[python]


def untrusted_helper() -> list:
    helper = os.environ.get("MLSBENCH_RUN_UNTRUSTED", "").split()
    return helper if helper and os.geteuid() == 0 else []


class Worker:
    def __init__(self, log_path: str, relay: VLMRelay, isolation: str, python: str):
        self.relay = relay
        self.log = open(log_path, "w")
        self.tmpdir = tempfile.mkdtemp(prefix="mlsb_agent_")
        self.isolation = isolation
        env = {
            "PATH": os.environ.get("PATH", "/usr/local/bin:/usr/bin:/bin"),
            "HOME": self.tmpdir, "TMPDIR": self.tmpdir, "LANG": "C.UTF-8",
            "PYTHONDONTWRITEBYTECODE": "1", "PYTHONUNBUFFERED": "1",
            "PYTHONPATH": trusted_site_path(python),
            "OMP_NUM_THREADS": "1", "MKL_NUM_THREADS": "1", "OPENBLAS_NUM_THREADS": "1",
            "MLSB_YOLO_WEIGHTS": os.environ.get("MLSB_YOLO_WEIGHTS", ""),
            "YOLO_CONFIG_DIR": self.tmpdir, "YOLO_OFFLINE": "1",
        }
        flags = ["-S", "-B", "-s"] + (["-P"] if sys.version_info >= (3, 11) else [])
        worker_cmd = [python, *flags, os.path.join(_HERE, "agent_worker.py")]
        kwargs: dict = {"env": env}
        if isolation == "helper":
            cmd = (untrusted_helper() + ["--stdio", "inherit", "--clean-env", "--writable", self.tmpdir]
                   + [f"--env={k}={v}" for k, v in env.items() if k not in ("HOME", "TMPDIR")]
                   + ["--"] + worker_cmd)
            kwargs = {}
        elif isolation == "uid":
            os.chmod(self.tmpdir, 0o777)
            cmd = worker_cmd
            kwargs.update(user=WORKER_UID, group=WORKER_UID, extra_groups=[])
        else:
            cmd = worker_cmd
        self.proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=self.log,
                                     cwd=self.tmpdir, text=True, bufsize=1, close_fds=True, **kwargs)

    def _readline(self, timeout: float) -> str:
        deadline = time.time() + timeout
        while True:
            rem = deadline - time.time()
            if rem <= 0:
                raise TimeoutError("worker reply timeout")
            r, _, _ = select.select([self.proc.stdout], [], [], min(rem, 5.0))
            if r:
                line = self.proc.stdout.readline()
                if not line:
                    raise RuntimeError("worker exited")
                return line
            if self.proc.poll() is not None:
                raise RuntimeError(f"worker exited rc={self.proc.returncode}")

    def call(self, msg: dict, timeout: float = WORKER_REPLY_TIMEOUT_S) -> dict:
        self.proc.stdin.write(json.dumps(msg) + "\n")
        self.proc.stdin.flush()
        deadline = time.time() + timeout
        while True:
            line = self._readline(max(1.0, deadline - time.time()))
            try:
                rep = json.loads(line)
            except json.JSONDecodeError:
                raise RuntimeError(f"worker protocol garbage: {line[:200]!r}")
            if rep.get("type") == "vlm":
                out = self.relay.request(rep)
                self.proc.stdin.write(json.dumps(out) + "\n")
                self.proc.stdin.flush()
                continue
            if rep.get("type") == "error":
                raise RuntimeError(f"policy error: {rep.get('message')}")
            return rep

    def close(self) -> None:
        try:
            if self.proc.poll() is None:
                try:
                    self.proc.stdin.write(json.dumps({"type": "shutdown"}) + "\n")
                    self.proc.stdin.flush()
                except Exception:  # noqa: BLE001
                    pass
                try:
                    self.proc.stdin.close()
                except Exception:  # noqa: BLE001
                    pass
                try:
                    self.proc.wait(timeout=20 if self.isolation == "helper" else 5)
                except Exception:  # noqa: BLE001
                    self.proc.terminate()
                    try:
                        self.proc.wait(timeout=30)
                    except Exception:  # noqa: BLE001
                        self.proc.kill()
                        self.proc.wait()
        finally:
            self.log.close()
            shutil.rmtree(self.tmpdir, ignore_errors=True)


def _enc_obs(obs: dict) -> dict:
    return {"images": {k: base64.b64encode(v).decode("ascii") for k, v in obs["images"].items()},
            "info": obs.get("info", {})}


# ---------------------------------------------------------------------------
# One shard = one simulator instance over a contiguous run of episodes of one subset
# ---------------------------------------------------------------------------
_CFG: dict = {}


def _init_pool(cfg: dict) -> None:
    global _CFG
    _CFG = cfg


def _budget(spec: dict, steps: int, invalid: int, calls: int) -> dict:
    return {"env_steps_used": steps, "max_env_steps": spec["max_env_steps"], "invalid_actions": invalid,
            "max_invalid_actions": spec["max_invalid_actions"], "vlm_calls_used": calls,
            "max_vlm_calls": spec["max_vlm_calls"]}


def run_episode(adapter, ep_idx: int, subset: str, local_idx: int, cfg: dict) -> dict:
    t0 = time.time()
    envname = cfg["env"]
    rec = {"idx": ep_idx, "subset": subset, "subset_idx": local_idx, "success": False, "env_steps": 0,
           "invalid_actions": 0, "vlm_calls": 0, "plans": 0, "malformed": 0, "error": None, "trajectory": []}
    relay = VLMRelay(cfg["llm_base_url"], cfg["model"], cfg["api_key"], cfg["seed"], ep_idx, MAX_VLM_CALLS[envname])
    worker = None
    try:
        try:
            instruction, obs = adapter.reset()
        except Exception as e:  # noqa: BLE001
            raise SimError(f"reset: {type(e).__name__}: {str(e)[:400]}") from e
        rec["instruction"] = instruction
        spec = dict(adapter.spec())
        spec["max_vlm_calls"] = MAX_VLM_CALLS[envname]
        rec["task_family"] = spec.get("task_family", "")
        worker = Worker(os.path.join(cfg["out"], "workers", f"ep_{ep_idx:03d}.log"), relay,
                        cfg["isolation"], cfg["python"])
        rep = worker.call({"type": "init", "env": spec, "seed": cfg["seed"]})
        if rep.get("type") != "ready":
            raise RuntimeError(f"worker init: {rep}")
        worker.call({"type": "reset", "instruction": instruction, "obs": _enc_obs(obs),
                     "budget": _budget(spec, 0, 0, relay.calls_used)})
        history: list = []
        steps, invalid, done, success = 0, 0, False, False
        max_acts = MAX_ACT_CALLS_FACTOR * (spec["max_env_steps"] + spec["max_invalid_actions"])
        while not done:
            if rec["plans"] >= max_acts:
                rec["error"] = "act-call limit reached"
                break
            if time.time() - t0 > EPISODE_WALL_CLOCK_S:
                rec["error"] = "episode wall clock exceeded"
                break
            rep = worker.call({"type": "act", "obs": _enc_obs(obs), "history": history,
                               "budget": _budget(spec, steps, invalid, relay.calls_used)})
            rec["plans"] += 1
            plan = rep.get("actions", []) if rep.get("type") == "plan" else []
            if not plan:
                rec["trajectory"].append({"plan": [], "note": "empty plan: episode ends"})
                break
            executed = []
            for raw in plan[: spec["max_env_steps"] - steps]:
                action = adapter.validate(raw)
                if action is None:
                    invalid += 1
                    rec["malformed"] += 1
                    r = {"step": 0, "action": raw, "action_text": str(raw)[:200],
                         "feedback": "Last action is invalid: it is not a well-formed action for this embodiment.",
                         "valid": False, "done": invalid >= spec["max_invalid_actions"]}
                    history.append(r)
                    executed.append(r)
                    if invalid >= spec["max_invalid_actions"]:
                        done = True
                    break      # a malformed action always returns control to the policy
                try:
                    obs, r, done, success = adapter.step(action)
                except Exception as e:  # noqa: BLE001
                    raise SimError(f"step: {type(e).__name__}: {str(e)[:400]}") from e
                steps += 1
                if not r["valid"] and envname == "habitat":
                    invalid += 1     # EBHabEnv counts simulator-rejected skills toward its limit
                    if invalid >= spec["max_invalid_actions"]:
                        done = True  # (shared with malformed outputs, as in the EB evaluator)
                r["step"] = steps
                history.append(r)
                executed.append(r)
                if success or done:
                    done = True
                    break
                if time.time() - t0 > EPISODE_WALL_CLOCK_S:
                    break
                keep = worker.call({"type": "observe", "record": r, "obs": _enc_obs(obs),
                                    "budget": _budget(spec, steps, invalid, relay.calls_used)})
                if not keep.get("value", True):
                    break
            rec["trajectory"].append({"plan": plan[:40], "executed": [
                {k: e[k] for k in ("step", "action_text", "feedback", "valid")} for e in executed]})
            if steps >= spec["max_env_steps"]:
                done = True
        rec["success"] = bool(success)
        rec["env_steps"] = steps
        rec["invalid_actions"] = invalid
    except SimError:
        raise                  # the simulator, not the policy, failed: run_shard restarts it and reruns
    except Exception as e:  # noqa: BLE001 - a broken policy is a failed episode, not a crashed run
        rec["error"] = f"{type(e).__name__}: {str(e)[:500]}"
        print(f"[episode {ep_idx}] {rec['error']}", file=sys.stderr)
        traceback.print_exc(file=sys.stderr)
    finally:
        if worker is not None:
            worker.close()
    rec["vlm_calls"] = relay.calls_used
    rec["prompt_tokens"] = relay.prompt_tokens
    rec["completion_tokens"] = relay.completion_tokens
    rec["vlm_errors"] = relay.errors
    rec["elapsed_s"] = round(time.time() - t0, 2)
    return rec


def _sink(path, rec: dict) -> None:
    if path:
        with open(path, "a") as f:
            f.write(json.dumps(rec) + "\n")


def _infra_record(gidx: int, subset: str, lidx: int, msg: str) -> dict:
    return {"idx": gidx, "subset": subset, "subset_idx": lidx, "success": False,
            "infra_error": msg, "error": msg, "env_steps": 0, "invalid_actions": 0,
            "vlm_calls": 0, "plans": 0, "malformed": 0, "prompt_tokens": 0,
            "completion_tokens": 0, "vlm_errors": 0, "elapsed_s": 0.0, "trajectory": []}


def _shard_entry(cfg: dict, job: tuple, path: str) -> None:
    _init_pool(cfg)
    run_shard(job, sink=path)


def run_shard(job: tuple, sink: str | None = None) -> list:
    """One simulator instance over a run of episodes. A simulator failure (a hung Unity backend,
    a crashed CoppeliaSim, ...) is not the policy's: the simulator is restarted and the episode is
    rerun from its reset with a fresh policy worker, up to SIM_RETRIES times; an episode that
    still cannot be run is an infrastructure error and invalidates the setting's metric."""
    subset, pairs = job                       # pairs: [(global_idx, subset_idx), ...]
    cfg = _CFG
    results = []
    k, retries = 0, 0
    while k < len(pairs):
        workdir = tempfile.mkdtemp(prefix=f"mlsb_sim_{cfg['env']}_")
        adapter = None
        try:
            adapter = eb_envs.ADAPTERS[cfg["env"]](cfg["episodes_dir"], subset, [p[1] for p in pairs[k:]], workdir)
            while k < len(pairs):
                gidx, lidx = pairs[k]
                rec = run_episode(adapter, gidx, subset, lidx, cfg)
                results.append(rec)
                _sink(sink, rec)
                k, retries = k + 1, 0
        except Exception as e:  # noqa: BLE001 - SimError or a simulator that cannot start
            msg = f"{type(e).__name__}: {str(e)[:500]}"
            print(f"[shard {subset}] simulator failure at episode {pairs[k][0]} (retry {retries}): {msg}",
                  file=sys.stderr)
            traceback.print_exc(file=sys.stderr)
            retries += 1
            if retries > SIM_RETRIES:
                rec = _infra_record(pairs[k][0], subset, pairs[k][1], msg)
                results.append(rec)
                _sink(sink, rec)
                k, retries = k + 1, 0
        finally:
            if adapter is not None:
                try:
                    adapter.close()
                except Exception:  # noqa: BLE001
                    pass
            shutil.rmtree(workdir, ignore_errors=True)
    return results


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--env", required=True, choices=sorted(eb_envs.ADAPTERS))
    ap.add_argument("--episodes-archive", default=None, help="tar holding eb_episodes/ (the verifier-side copy)")
    ap.add_argument("--episodes-root", default=None, help="directory holding habitat/ navigation/ manipulation/ + index.json")
    ap.add_argument("--llm-base-url", required=True)
    ap.add_argument("--model", default="agent-vlm")
    ap.add_argument("--seed", type=int, default=0)
    ap.add_argument("--out", required=True)
    ap.add_argument("--parallel", type=int, default=8)
    ap.add_argument("--shards-per-slot", type=int, default=2)
    ap.add_argument("--max-episodes", type=int, default=0,
                    help="smoke knob: >0 runs N evenly spaced episodes of every subset and NEVER yields a scored metric")
    ap.add_argument("--python", default=sys.executable)
    args = ap.parse_args()

    os.makedirs(os.path.join(args.out, "workers"), exist_ok=True)
    atexit.register(_restore_modes)
    for secret_dir in ("/tests/meta", "/solution"):
        _seal_dir(secret_dir)
    episodes_dir = stage_episodes(args.episodes_archive, args.episodes_root)
    with open(os.path.join(episodes_dir, "index.json")) as f:
        index = json.load(f)[args.env]           # {subset: n_episodes}
    smoke = args.max_episodes > 0
    episodes = []
    for subset in eb_envs.SUBSETS[args.env]:
        n = int(index[subset])
        if smoke:
            # evenly spaced over the subset (episode files are grouped by task family / scene)
            k = min(n, args.max_episodes)
            picks = sorted({(i * n) // k for i in range(k)})
        else:
            picks = range(n)
        for i in picks:
            episodes.append((len(episodes), subset, i))
    # shards: contiguous runs within a subset, about shards_per_slot per slot
    n_shards = max(1, args.parallel * args.shards_per_slot)
    per = max(1, -(-len(episodes) // n_shards))
    jobs = []
    for subset in eb_envs.SUBSETS[args.env]:
        eps = [(g, i) for g, s, i in episodes if s == subset]
        for k in range(0, len(eps), per):
            jobs.append((subset, eps[k:k + per]))
    jobs.sort(key=lambda j: -len(j[1]))

    if untrusted_helper():
        isolation = "helper"
    elif os.geteuid() == 0:
        isolation = "uid"
        try:
            pwd.getpwuid(WORKER_UID)
        except KeyError:
            pass
    else:
        isolation = "none"
    print(f"[harness] env={args.env} episodes={len(episodes)} shards={len(jobs)} seed={args.seed} "
          f"parallel={args.parallel} worker_isolation={isolation} budget=env_steps:{eb_envs.LIMITS[args.env]['max_env_steps']} "
          f"invalid:{eb_envs.LIMITS[args.env]['max_invalid_actions']} vlm_calls:{MAX_VLM_CALLS[args.env]}", flush=True)
    if isolation == "none":
        print("[harness] WARNING: not running as root; the policy worker shares this uid. "
              "Fine for a trusted measurement only.", flush=True)

    cfg = {"env": args.env, "episodes_dir": episodes_dir, "llm_base_url": args.llm_base_url, "model": args.model,
           "api_key": os.environ.get("VLLM_API_KEY", ""), "seed": args.seed, "out": args.out,
           "isolation": isolation, "python": args.python}
    t0 = time.time()
    results: list = []
    jsonl = open(os.path.join(args.out, "episodes.jsonl"), "w")
    ctx = get_context("spawn")
    shard_dir = tempfile.mkdtemp(prefix="mlsb_shards_")
    atexit.register(shutil.rmtree, shard_dir, True)
    # One process per shard (not a Pool): a simulator can take its whole process down (a
    # CoppeliaSim / Unity crash), which a Pool never reports. Each shard appends one JSON line
    # per finished episode; when a shard process dies, its unfinished episodes are requeued
    # (up to SIM_RETRIES times) and otherwise recorded as infrastructure errors.
    # The simulators render on the CPU. Keep the GPU out of their processes: with
    # CUDA_VISIBLE_DEVICES set, AI2-THOR picks a GPU and requires a working Vulkan device for it
    # (fatal on compute-only GPU hosts). On hosts that expose /dev/dri render nodes (Daytona),
    # Mesa lists them as EGL devices ahead of its software device and habitat-sim takes device 0,
    # which cannot be initialised there; the libnodrm shim (baked at build time) hides the DRM
    # devices from Mesa so the only EGL device is llvmpipe -- the same device as on hosts
    # without render nodes.
    for k in ("CUDA_VISIBLE_DEVICES", "NVIDIA_VISIBLE_DEVICES"):
        os.environ.pop(k, None)
    shim = os.environ.get("MLSB_NODRM_SHIM", "/opt/eb-data/libnodrm.so")
    if args.env == "habitat" and os.path.exists(shim):
        os.environ["LD_PRELOAD"] = shim
    queue_ = [(job, 0) for job in jobs]
    running: dict = {}
    seq = 0

    def _collect(path: str) -> list:
        out = []
        if os.path.exists(path):
            with open(path) as f:
                for line in f:
                    try:
                        out.append(json.loads(line))
                    except json.JSONDecodeError:
                        pass
        return out

    def _report(recs: list) -> None:
        for rec in recs:
            results.append(rec)
            jsonl.write(json.dumps(rec) + "\n")
        jsonl.flush()
        n = len(results)
        sr = sum(r["success"] for r in results) / max(1, n)
        print(f"TRAIN_METRICS: episodes_done={n}/{len(episodes)} success_rate_so_far={sr:.4f} "
              f"elapsed_s={time.time() - t0:.0f}", flush=True)

    while queue_ or running:
        while queue_ and len(running) < max(1, args.parallel):
            (subset, pairs), tries = queue_.pop(0)
            seq += 1
            path = os.path.join(shard_dir, f"shard_{seq:04d}.jsonl")
            proc = ctx.Process(target=_shard_entry, args=(cfg, (subset, pairs), path), daemon=False)
            proc.start()
            running[proc] = (subset, pairs, tries, path)
        time.sleep(2)
        for proc in [p_ for p_ in running if not p_.is_alive()]:
            proc.join()
            subset, pairs, tries, path = running.pop(proc)
            recs = _collect(path)
            done = {r["idx"] for r in recs}
            missing = [pr for pr in pairs if pr[0] not in done]
            if missing:
                msg = f"shard process exited with code {proc.exitcode} before finishing {len(missing)} episode(s)"
                print(f"[harness] {subset}: {msg}", file=sys.stderr, flush=True)
                if tries < SIM_RETRIES:
                    queue_.append(((subset, missing), tries + 1))
                else:
                    recs += [_infra_record(g, subset, l, msg) for g, l in missing]
            if recs:
                _report(recs)
    jsonl.close()
    results.sort(key=lambda r: r["idx"])

    n = len(results)
    n_infra = sum(1 for r in results if r.get("infra_error"))
    n_success = sum(1 for r in results if r["success"])
    n_err = sum(1 for r in results if r.get("error") and not r.get("infra_error"))
    by_subset = {}
    for s in eb_envs.SUBSETS[args.env]:
        rs = [r for r in results if r["subset"] == s]
        if rs:
            by_subset[s] = (sum(r["success"] for r in rs), len(rs))
    summary = {
        "env": args.env, "seed": args.seed, "n_episodes": n, "n_success": n_success,
        "success_rate": n_success / n if n else 0.0, "policy_errors": n_err, "infra_errors": n_infra,
        "mean_vlm_calls": sum(r["vlm_calls"] for r in results) / max(1, n),
        "mean_env_steps": sum(r["env_steps"] for r in results) / max(1, n),
        "mean_plans": sum(r["plans"] for r in results) / max(1, n),
        "mean_prompt_tokens": sum(r["prompt_tokens"] for r in results) / max(1, n),
        "mean_completion_tokens": sum(r["completion_tokens"] for r in results) / max(1, n),
        "by_subset": {s: {"n_success": a, "n": b, "success_rate": a / b} for s, (a, b) in by_subset.items()},
        "elapsed_s": time.time() - t0, "smoke": smoke, "worker_isolation": isolation,
        "budget": {"max_vlm_calls": MAX_VLM_CALLS[args.env], **eb_envs.LIMITS[args.env]},
    }
    with open(os.path.join(args.out, "summary.json"), "w") as f:
        json.dump(summary, f, indent=1)
    print("TEST_METRICS_BY_SUBSET: " + " ".join(f"{s}={a}/{b}" for s, (a, b) in by_subset.items()), flush=True)
    line = (f"success_rate={summary['success_rate']:.4f} n_episodes={n} n_success={n_success} "
            f"mean_vlm_calls={summary['mean_vlm_calls']:.2f} mean_env_steps={summary['mean_env_steps']:.2f} "
            f"policy_errors={n_err} infra_errors={n_infra} elapsed_s={summary['elapsed_s']:.0f}")
    if n_infra > 0:
        print(f"TEST_METRICS_INVALID: {n_infra} episode(s) lost to simulator failures -- {line}", flush=True)
        return 2
    if n and n_err == n:
        print(f"TEST_METRICS_INVALID: every episode raised a policy error -- {line}", flush=True)
        return 2
    if smoke:
        print(f"SMOKE_METRICS: {line}", flush=True)
        print(f"NOT A MEASUREMENT: --max-episodes={args.max_episodes} in force; no scored metric emitted", flush=True)
        return 3
    print(f"TEST_METRICS: {line}", flush=True)
    return 0


if __name__ == "__main__":
    sys.exit(main())

