    rec["vlm_calls"] = relay.calls_used
    rec["prompt_tokens"] = relay.prompt_tokens
    rec["completion_tokens"] = relay.completion_tokens
    rec["vlm_errors"] = relay.errors
    rec["elapsed_s"] = round(time.time() - t0, 2)
    return rec


def _sink(path, rec: dict) -> None:
    if path:
        with open(path, "a") as f:
            f.write(json.dumps(rec) + "\n")


def _infra_record(gidx: int, subset: str, lidx: int, msg: str) -> dict:
    return {"idx": gidx, "subset": subset, "subset_idx": lidx, "success": False,
            "infra_error": msg, "error": msg, "env_steps": 0, "invalid_actions": 0,
            "vlm_calls": 0, "plans": 0, "malformed": 0, "prompt_tokens": 0,
            "completion_tokens": 0, "vlm_errors": 0, "elapsed_s": 0.0, "trajectory": []}


def _shard_entry(cfg: dict, job: tuple, path: str) -> None:
    _init_pool(cfg)
    run_shard(job, sink=path)


def run_shard(job: tuple, sink: str | None = None) -> list:
    """One simulator instance over a run of episodes. A simulator failure (a hung Unity backend,
    a crashed CoppeliaSim, ...) is not the policy's: the simulator is restarted and the episode is
    rerun from its reset with a fresh policy worker, up to SIM_RETRIES times; an episode that
    still cannot be run is an infrastructure error and invalidates the setting's metric."""
    subset, pairs = job                       # pairs: [(global_idx, subset_idx), ...]
    cfg = _CFG
    results = []
    k, retries = 0, 0
    while k < len(pairs):
        workdir = tempfile.mkdtemp(prefix=f"mlsb_sim_{cfg['env']}_")
        adapter = None
        try:
            adapter = eb_envs.ADAPTERS[cfg["env"]](cfg["episodes_dir"], subset, [p[1] for p in pairs[k:]], workdir)
            while k < len(pairs):
                gidx, lidx = pairs[k]
                rec = run_episode(adapter, gidx, subset, lidx, cfg)
                results.append(rec)
                _sink(sink, rec)
                k, retries = k + 1, 0
        except Exception as e:  # noqa: BLE001 - SimError or a simulator that cannot start
            msg = f"{type(e).__name__}: {str(e)[:500]}"
            print(f"[shard {subset}] simulator failure at episode {pairs[k][0]} (retry {retries}): {msg}",
                  file=sys.stderr)
            traceback.print_exc(file=sys.stderr)
            retries += 1
            if retries > SIM_RETRIES:
                rec = _infra_record(pairs[k][0], subset, pairs[k][1], msg)
                results.append(rec)
                _sink(sink, rec)
                k, retries = k + 1, 0
        finally:
            if adapter is not None:
                try:
                    adapter.close()
                except Exception:  # noqa: BLE001
                    pass
            shutil.rmtree(workdir, ignore_errors=True)
    return results


